[CmdletBinding()]
param(
  [int]$Count = 10,
  [string]$RepoRoot = "",
  [int]$MaxTurns = 50,
  [switch]$NoPush,
40→  [switch]$DryRun
)

$ErrorActionPreference = "Stop"

if (-not $RepoRoot) {
  $RepoRoot = Split-Path -Parent (Split-Path -Parent $MyInvocation.MyCommand.Path)
}
