os.makedirs(dst_dir, exist_ok=True)

proc_names = set()
for dirpath, _, filenames in os.walk(proc):
    for n in filenames:
        if n != '.gitkeep':
            proc_names.add(n)
state_names = {c.get('source_basename') for c in state.get('cases', []) if c.get('source_basename')}

FN_DOCKET = re.compile(r'_(\d+)_(\d{4})\.pdf$', re.I)
