for n in os.listdir(summ):
    if not n.endswith('.json'): continue
    try:
        d = json.load(open(os.path.join(summ, n), encoding='utf-8'))
    except Exception:
        continue
    records.append((d.get('case_id') or '', d.get('docket') or ''))

def docket_hit(filename):
    m = FN_DOCKET.search(filename)
    if not m: return None
    num, year = m.group(1), m.group(2)
    nds = [f'No. {num} of {year}', f'No. - {num} of {year}', f'No.- {num} of {year}', f'No.{num} of {year}']
    for cid, dk in records:
        low = (dk or '').lower()
        for nd in nds:
            if nd.lower() in low:
                return cid, dk, nd
    return None

moved = []
