    dest = os.path.join(dst_dir, n)
    if os.path.exists(dest):
        os.remove(src)
        action = 'removed (already in processed/2025)'
    else:
        os.replace(src, dest)
        action = 'moved'
    moved.append((n, reason, extra, action))

print('moved', len(moved))
